import json,os,sys,time
root=sys.argv[1];output=sys.argv[2];stop=sys.argv[3];ticks=os.sysconf('SC_CLK_TCK');page=os.sysconf('SC_PAGE_SIZE');previous={}
with open(output,'w') as f:
 while not os.path.exists(stop):
  now=time.time()
  for name in os.listdir('/proc'):
   if not name.isdigit():continue
   try:
    cmd=open('/proc/'+name+'/cmdline','rb').read().split(b'\0')
    if not cmd or not cmd[0].endswith(b'/bin/java') or b'-Xms64g' not in cmd:continue
    if not any(root.encode() in arg and b'surefirebooter' in arg for arg in cmd):continue
    st=open('/proc/'+name+'/stat').read().rsplit(')',1)[1].split();cpu=int(st[11])+int(st[12]);p=previous.get(name);pct=(cpu-p[1])/ticks/(now-p[0])*100 if p and now>p[0] else None
    row={'epoch_ms':round(now*1000),'pid':int(name),'cpu_percent':pct,'rss_bytes':int(st[21])*page,'minor_faults':int(st[7]),'major_faults':int(st[9]),'threads':int(st[17])}
    previous[name]=(now,cpu);f.write(json.dumps(row)+'\n');f.flush()
   except (OSError,ValueError,IndexError):continue
